public class BasicSerializerFactory_buildContainerSerializer_TriageGen1Test {

    private BasicSerializerFactory factory;
    private SerializerProvider prov;
    private SerializationConfig config;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // A concrete implementation to test the protected method
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        private final Serializers customSerializers;

        public TestableBasicSerializerFactory(SerializerFactoryConfig config, Serializers customSerializers) {
            super(config);
            this.customSerializers = customSerializers;
        }

        @Override
        protected Iterable<Serializers> customSerializers() {
            return customSerializers;
        }

        @Override
        public JsonSerializer<Object> createSerializer(SerializerProvider prov, JavaType type) throws JsonMappingException {
            return null;
        }

        // Overriding to avoid NPE in the logic during testing
        @Override
        protected TypeSerializer createTypeSerializer(SerializationConfig config, JavaType baseType) {
            return null; 
        }

        @Override
        protected JsonSerializer<Object> _findKeySerializer(SerializerProvider prov, com.fasterxml.jackson.databind.introspect.Annotated a) {
            return null;
        }

        @Override
        protected JsonSerializer<Object> _findContentSerializer(SerializerProvider prov, com.fasterxml.jackson.databind.introspect.Annotated a) {
            return null;
        }

        @Override
        protected JsonSerializer<?> buildMapSerializer(SerializationConfig config, MapType type, BeanDescription beanDesc, boolean staticTyping, JsonSerializer<Object> keySerializer, TypeSerializer elementTypeSerializer, JsonSerializer<Object> elementValueSerializer) {
            return mock(JsonSerializer.class);
        }

        @Override
        protected JsonSerializer<?> buildCollectionSerializer(SerializationConfig config, CollectionType type, BeanDescription beanDesc, boolean staticTyping, TypeSerializer elementTypeSerializer, JsonSerializer<Object> elementValueSerializer) {
            return mock(JsonSerializer.class);
        }

        @Override
        protected JsonSerializer<?> buildArraySerializer(SerializationConfig config, ArrayType type, BeanDescription beanDesc, boolean staticTyping, TypeSerializer elementTypeSerializer, JsonSerializer<Object> elementValueSerializer) {
            return mock(JsonSerializer.class);
        }
    }

    @Before
    public void setUp() {
        prov = mock(SerializerProvider.class);
        config = mock(SerializationConfig.class);
        beanDesc = mock(BeanDescription.class);
        typeFactory = TypeFactory.defaultInstance();
        when(prov.getConfig()).thenReturn(config);
        factory = new TestableBasicSerializerFactory(mock(SerializerFactoryConfig.class), Collections.emptyList());
    }

    @Test
    public void testStaticTypingLogic_ForceStatic() throws JsonMappingException {
        // Case: !staticTyping && type.useStaticType() && !isContainer || content != Object
        JavaType type = typeFactory.constructType(String[].class); 
        // String[].class is an array, useStaticType is true, content type is String (not Object)

        // We need to access the protected method via the testable subclass
        JsonSerializer<?> result = factory.buildContainerSerializer(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testMapLikeType_TrueMap() throws JsonMappingException {
        MapType mapType = typeFactory.constructMapType(java.util.HashMap.class, Object.class, Object.class);
        JsonSerializer<?> result = factory.buildContainerSerializer(prov, mapType, beanDesc, true);
        assertNotNull(result);
    }

    @Test
    public void testMapLikeType_CustomSerializer() throws JsonMappingException {
        MapType mapType = typeFactory.constructMapType(java.util.HashMap.class, Object.class, Object.class);

        Serializers mockSerializers = mock(Serializers.class);
        JsonSerializer<?> customSer = mock(JsonSerializer.class);
        when(mockSerializers.findMapLikeSerializer(any(), any(), any(), any(), any(), any())).thenReturn(customSer);

        TestableBasicSerializerFactory customFactory = new TestableBasicSerializerFactory(
                factory.getFactoryConfig(), 
                Collections.singletonList(mockSerializers)
        );

        JsonSerializer<?> result = customFactory.buildContainerSerializer(prov, mapType, beanDesc, true);
        assertEquals(customSer, result);
    }

    @Test
    public void testCollectionLikeType_TrueCollection() throws JsonMappingException {
        CollectionType collType = typeFactory.constructCollectionType(java.util.ArrayList.class, Object.class);
        JsonSerializer<?> result = factory.buildContainerSerializer(prov, collType, beanDesc, true);
        assertNotNull(result);
    }

    @Test
    public void testCollectionLikeType_CustomSerializer() throws JsonMappingException {
        CollectionType collType = typeFactory.constructCollectionType(java.util.ArrayList.class, Object.class);

        Serializers mockSerializers = mock(Serializers.class);
        JsonSerializer<?> customSer = mock(JsonSerializer.class);
        when(mockSerializers.findCollectionLikeSerializer(any(), any(), any(), any(), any())).thenReturn(customSer);

        TestableBasicSerializerFactory customFactory = new TestableBasicSerializerFactory(
                factory.getFactoryConfig(), 
                Collections.singletonList(mockSerializers)
        );

        JsonSerializer<?> result = customFactory.buildContainerSerializer(prov, collType, beanDesc, true);
        assertEquals(customSer, result);
    }

    @Test
    public void testArrayType() throws JsonMappingException {
        ArrayType arrayType = typeFactory.constructArrayType(String.class);
        JsonSerializer<?> result = factory.buildContainerSerializer(prov, arrayType, beanDesc, true);
        assertNotNull(result);
    }

    @Test
    public void testElementTypeSerializerFound_SetsStaticTypingFalse() throws JsonMappingException {
        // If elementTypeSerializer != null, staticTyping = false
        // To achieve this, we must mock createTypeSerializer in the factory

        JavaType type = typeFactory.constructArrayType(String.class);

        // We create a custom factory that returns a non-null TypeSerializer
        TestableBasicSerializerFactory factoryWithTypeSer = new TestableBasicSerializerFactory(factory.getFactoryConfig(), Collections.emptyList()) {
            @Override
            protected TypeSerializer createTypeSerializer(SerializationConfig config, JavaType baseType) {
                return mock(TypeSerializer.class);
            }
        };

        // Since we can't easily check the internal 'staticTyping' boolean value after the method returns,
        // we rely on the fact that the method completes without error. 
        // In a real scenario, we'd verify the behavior of buildCollectionSerializer which receives this flag.
        JsonSerializer<?> result = factoryWithTypeSer.buildContainerSerializer(prov, type, beanDesc, true);
        assertNotNull(result);
    }

    @Test
    public void testMapLikeType_NoCustomAndNoTrueMap_ReturnsNull() throws JsonMappingException {
        // Create a type that is MapLike but not "TrueMap" (unlikely with standard Jackson types, but for branch coverage)
        // For this test, we simulate a MapLikeType that is not a true map via mocking if possible, 
        // or use a type that is MapLike but fails the isTrueMapType check.
        // Since MapLikeType is an abstract class/interface behavior, we use a mock.

        MapType mockMapType = mock(MapType.class);
        when(mockMapType.isMapLikeType()).thenReturn(true);
        when(mockMapType.isTrueMapType()).thenReturn(false);
        when(mockMapType.getContentType()).thenReturn(typeFactory.constructType(Object.class));

        JsonSerializer<?> result = factory.buildContainerSerializer(prov, mockMapType, beanDesc, true);
        assertNull(result);
    }

    @Test
    public void testCollectionLikeType_NoCustomAndNoTrueCollection_ReturnsNull() throws JsonMappingException {
        CollectionType mockCollType = mock(CollectionType.class);
        when(mockCollType.isCollectionLikeType()).thenReturn(true);
        when(mockCollType.isTrueCollectionType()).thenReturn(false);
        when(mockCollType.getContentType()).thenReturn(typeFactory.constructType(Object.class));

        JsonSerializer<?> result = factory.buildContainerSerializer(prov, mockCollType, beanDesc, true);
        assertNull(result);
    }

    @Test
    public void testSerializerModifierOnMapLike() throws JsonMappingException {
        MapType mapType = typeFactory.constructMapType(java.util.HashMap.class, Object.class, Object.class);

        Serializers mockSerializers = mock(Serializers.class);
        JsonSerializer<?> customSer = mock(JsonSerializer.class);
        when(mockSerializers.findMapLikeSerializer(any(), any(), any(), any(), any(), any())).thenReturn(customSer);

        BeanSerializerModifier mockModifier = mock(BeanSerializerModifier.class);
        JsonSerializer<?> modifiedSer = mock(JsonSerializer.class);
        when(mockModifier.modifyMapLikeSerializer(any(), any(), any(), any())).thenReturn(modifiedSer);

        // We need a factory config that has modifiers
        SerializerFactoryConfig mockConfig = mock(SerializerFactoryConfig.class);
        when(mockConfig.hasSerializerModifiers()).thenReturn(true);
        when(mockConfig.serializerModifiers()).thenReturn(Collections.singletonList(mockModifier));

        TestableBasicSerializerFactory customFactory = new TestableBasicSerializerFactory(
                mockConfig, 
                Collections.singletonList(mockSerializers)
        );

        JsonSerializer<?> result = customFactory.buildContainerSerializer(prov, mapType, beanDesc, true);
        assertEquals(modifiedSer, result);
    }

    @Test
    public void testSerializerModifierOnCollectionLike() throws JsonMappingException {
        CollectionType collType = typeFactory.constructCollectionType(java.util.ArrayList.class, Object.class);

        Serializers mockSerializers = mock(Serializers.class);
        JsonSerializer<?> customSer = mock(JsonSerializer.class);
        when(mockSerializers.findCollectionLikeSerializer(any(), any(), any(), any(), any())).thenReturn(customSer);

        BeanSerializerModifier mockModifier = mock(BeanSerializerModifier.class);
        JsonSerializer<?> modifiedSer = mock(JsonSerializer.class);
        when(mockModifier.modifyCollectionLikeSerializer(any(), any(), any(), any())).thenReturn(modifiedSer);

        SerializerFactoryConfig mockConfig = mock(SerializerFactoryConfig.class);
        when(mockConfig.hasSerializerModifiers()).thenReturn(true);
        when(mockConfig.serializerModifiers()).thenReturn(Collections.singletonList(mockModifier));

        TestableBasicSerializerFactory customFactory = new TestableBasicSerializerFactory(
                mockConfig, 
                Collections.singletonList(mockSerializers)
        );

        JsonSerializer<?> result = customFactory.buildContainerSerializer(prov, collType, beanDesc, true);
        assertEquals(modifiedSer, result);
    }
}
